[asy]
unitsize(0.2 cm);

real parab (real x) {
  return(x^2/8);
}

pair A, B, O;

A = (8*sqrt(3),24);
B = (-8*sqrt(3),24);
O = (0,0);

draw(O--A--B--cycle);
draw(graph(parab,-15,15));

dot("$A = (a,\frac{a^2}{8})$", A, E);
dot("$B = (-a,\frac{a^2}{8})$", B, W);
dot("$O = (0,0)$", O, S);
[/asy]

